outcomes.query:
WITH RECURSIVE chain(item) AS (
  SELECT item FROM waits_on WHERE upstream = 'procurement_freeze'
  UNION
  SELECT w.item FROM waits_on w JOIN chain c ON w.upstream = c.item
)
SELECT item FROM chain;

WITH RECURSIVE chain(item) AS (
  SELECT 'atlas'
  UNION
  SELECT w.upstream FROM waits_on w JOIN chain c ON w.item = c.item
)
SELECT CASE WHEN EXISTS (SELECT 1 FROM chain WHERE item = 'procurement_freeze') THEN 'yes' ELSE 'no' END;
